{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C57", "C61", "C53", "C49", "C48", "C45", "C54", "C04", "C10", "C14", "C07", "C11", "C08", "C02"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C57", "C61", "C53", "C49", "C04", "C10", "C14", "C07", "C11", "C08"],
  "claims": [
    {
      "claim": "L5 morphine records are the most relevant gut-wall evidence: morphine is rapidly absorbed from the small intestine in rats (C57), and in Caco-2 it is transported at a much higher rate than mannitol and PEG4000 with a literature oral bioavailability of 80% (C61). The query is the 6-keto analogue of morphine, so these records support a high absorption component for the query.",
      "card_ids": ["C57", "C61"]
    },
    {
      "claim": "No L5 record shows gut-wall efflux or intestinal metabolism for the query or for close opioid analogues. The efflux and permeability records concern estrone (C56), estrone-3-sulfate (C62), naringenin (C59, C66), hesperetin (C58), bilobalide (C63), levofloxacin (C60, C64, C65), and ofloxacin (C55), which are not applicable to the query scaffold.",
      "card_ids": ["C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64", "C65", "C66"]
    },
    {
      "claim": "Visible opioid systemic-F records remain above the 20% threshold: codeine absolute F 80.5% (C04), pethidine 0.80 ± 0.15 (C10, C14), pentazocine 0.68 to 0.70 (C07, C11), meptazinol 27.9% (C08), and naloxegol simulated F 0.90 (C02). No affirmative threshold-relevant evidence supports F below 20% for the query.",
      "card_ids": ["C04", "C10", "C14", "C07", "C11", "C08", "C02"]
    },
    {
      "claim": "L4 absorption and solubility records for close opioid analogues remain supportive: codeine F_abs greater than 90% (C53) and high solubility (C49), morphine sulfate solubility 64.5 mg/mL (C48), and dextromethorphan complete or near-complete GI absorption (C45, C54).",
      "card_ids": ["C53", "C49", "C48", "C45", "C54"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64", "C65", "C66"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present in the visible set.",
    "No hydromorphone-specific gut-wall efflux or intestinal metabolism data are available; morphine is a close analogue but not the query.",
    "Several opioid F records are cirrhosis-conditioned, and cirrhosis increases F by reducing first-pass metabolism, so healthy-subject transfer is uncertain.",
    "Codeine relative bioavailability (C17, C30) is versus intramuscular dosing, not intravenous, so it is not a pure absolute F value.",
    "Naloxegol F 0.90 is a PBPK simulation (C02), not a measured clinical absolute F for the query scaffold.",
    "No dose-, formulation-, or prandial-state-matched hydromorphone data are available."
  ],
  "decision_summary": "L5 gut-wall efflux and intestinal metabolism records provide no affirmative low-F evidence for the query. The most relevant L5 records concern morphine, the direct 6-deoxo analogue scaffold, showing rapid small-intestinal absorption and literature F of 80% (C57, C61). Combined with opioid systemic-F records above 20% and no affirmative contradictory evidence, the high prediction is strengthened and confidence remains high."
}

